var days=[
  {d:'今日',date:'10/11',icon:'cloud-sun',cond:'多云',hi:26,lo:17},
  {d:'周一',date:'10/12',icon:'sun',cond:'晴',hi:28,lo:18},
  {d:'周二',date:'10/13',icon:'sun',cond:'晴',hi:27,lo:19},
  {d:'周三',date:'10/14',icon:'cloud-rain',cond:'小雨',hi:24,lo:16},
  {d:'周四',date:'10/15',icon:'cloud-sun',cond:'多云',hi:25,lo:17},
  {d:'周五',date:'10/16',icon:'cloud-rain',cond:'中雨',hi:22,lo:15},
  {d:'周六',date:'10/17',icon:'cloud-sun',cond:'多云',hi:23,lo:16}
];
var hourly=[18,19,20,22,24,26,25,23,21];
var hourlyL=['08','10','12','14','16','18','20','22','24'];
var selected=0;
function paintHero(i){
  var x=days[i];
  document.getElementById('hero-loc').textContent='上海 · '+x.date+' · '+x.d;
  document.getElementById('hero-temp').textContent=x.hi+'°';
  document.getElementById('hero-cond').textContent=x.cond;
  document.getElementById('hero-icon').setAttribute('data-iui-icon',x.icon);
  document.getElementById('hero-range').textContent=x.hi+'° / '+x.lo+'°';
  document.querySelectorAll('.iui-weather-day').forEach(function(el,idx){
    el.setAttribute('aria-current', idx===i?'true':'false');
  });
}
function paintDays(){
  var row=document.getElementById('days');
  row.innerHTML='';
  days.forEach(function(x,i){
    var b=document.createElement('button');
    b.type='button';
    b.className='iui-weather-day';
    b.innerHTML='<span class="wd">'+x.d+'</span><span class="dt">'+x.date+'</span><span class="ic"><i data-iui-icon="'+x.icon+'"></i></span><span class="cd">'+x.cond+'</span><span class="rg">'+x.hi+'°/'+x.lo+'°</span>';
    b.onclick=function(){ selected=i; paintHero(i); window.iuiSandbox.action('weather_day',{i:i,day:x.d}); };
    row.appendChild(b);
  });
  paintHero(selected);
}
paintDays();
(function paintChart(){
  var ctx=document.getElementById('wxChart');
  if(!ctx) return;
  var Chart=window.Chart;
  if(!Chart){ setTimeout(paintChart, 40); return; }
  if(window.iuiCreateChart){
    window.iuiCreateChart(ctx,{
      type:'line',
      data:{labels:hourlyL,datasets:[{label:'气温',data:hourly}]},
      options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:false,ticks:{callback:function(v){return v+'°'}}}}}
    });
  } else {
    new Chart(ctx,{type:'line',data:{labels:hourlyL,datasets:[{label:'气温',data:hourly}]},options:{maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:false}}}});
  }
  ctx.__iuiChartOk=true;
  window.iuiSandbox&&window.iuiSandbox.resize();
})();

